mapper.select:
SELECT

FROM post p
LEFT JOIN `user` u ON u.id = p.user_id AND u.is_deleted = 0

    p.is_deleted = 0

        AND (
            p.is_pinned < #{cursorPinned}
            OR (p.is_pinned = #{cursorPinned} AND p.create_time < #{cursorCreateTime})
            OR (p.is_pinned = #{cursorPinned} AND p.create_time = #{cursorCreateTime}
                AND p.id < #{cursorId})
        )


ORDER BY p.is_pinned DESC, p.create_time DESC, p.id DESC
LIMIT #{limit}
